{
  "name": "Jikbo Generator",
  "description": "Generates a 4-page Final Exam Review (Jikbo) document from English textbook PDFs using Gemini."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface JikboData {
  meta: {
    publisher: string;
    grade: string;
    lesson: string;
    schoolLevel: string;
  };
  vocab: {
    synonyms: string[];
    antonyms: string[];
    collocations: string[];
    definitions: { word: string; meaning: string; enDefinition: string }[];
  };
  dialog: {
    part1: {
      title: string;
      mainExpression: string;
      explanation: string;
      variations: string[];
      responseGood: string[];
      responseBad: string[];
    };
    part2: {
      title: string;
      mainExpression: string;
      explanation: string;
      variations: string[];
    };
    extra: { expression: string; meaning: string; note: string }[];
  };
  grammar: {
    point1: {
      title: string;
      description: string;
      construction: string;
      examples: { en: string; ko: string }[];
    };
    point2: {
      title: string;
      description: string;
      construction: string;
      examples: { en: string; ko: string }[];
    };
  };
  reading: {
    title: string;
    subtitle: string;
    paragraphs: { en: string; ko: string; grammarNote?: string }[];
  };
}

export enum AppStatus {
  IDLE,
  PROCESSING,
  SUCCESS,
  ERROR,
}

import { GoogleGenAI, Type } from "@google/genai";
import { JikboData } from "./types";

export const generateJikboData = async (
  apiKey: string,
  base64File: string,
  mimeType: string,
  userInstruction: string
): Promise<JikboData> => {
  const ai = new GoogleGenAI({ apiKey });

  const systemInstruction = `You are an expert Korean middle school English teacher creating a "Jikbo" (Final Exam Last Minute Review) document.
  Analyze the provided textbook PDF/Image materials.
  Extract content to fill a strict JSON schema for a 4-page review sheet.

  Language: Korean (for explanations/definitions) and English (for content).

  Structure requirements:
  1. Vocabulary: Extract synonyms, antonyms, and English definitions of key words.
  2. Dialog: Identify 2 key communicative functions (Listen & Talk), their variations, and correct/incorrect responses.
  3. Grammar: Identify the 2 main grammar points of the lesson. Provide construction rules and examples.
  4. Reading: Extract the main reading passage. Break it down sentence-by-sentence with Korean translations and brief grammar notes (e.g., "to infinitive used as noun").

  If the file contains multiple lessons, focus on the lesson mentioned in the user instruction or the first full lesson found.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: mimeType,
            data: base64File,
          },
        },
        {
          text: `Generate Jikbo data. Context: ${userInstruction}. Return ONLY JSON.`,
        },
      ],
    },
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          meta: {
            type: Type.OBJECT,
            properties: {
              publisher: { type: Type.STRING, description: "e.g., 동아(윤)" },
              grade: { type: Type.STRING, description: "e.g., 2" },
              lesson: { type: Type.STRING, description: "e.g., Lesson 08" },
              schoolLevel: { type: Type.STRING, description: "e.g., MIDDLE SCHOOL" },
            },
          },
          vocab: {
            type: Type.OBJECT,
            properties: {
              synonyms: { type: Type.ARRAY, items: { type: Type.STRING }, description: "e.g., 'royal(왕의) = regal'" },
              antonyms: { type: Type.ARRAY, items: { type: Type.STRING }, description: "e.g., 'allow(허락하다) ↔ forbid(금지하다)'" },
              collocations: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Idioms or phrases" },
              definitions: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    word: { type: Type.STRING },
                    meaning: { type: Type.STRING },
                    enDefinition: { type: Type.STRING },
                  },
                },
              },
            },
          },
          dialog: {
            type: Type.OBJECT,
            properties: {
              part1: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  mainExpression: { type: Type.STRING },
                  explanation: { type: Type.STRING },
                  variations: { type: Type.ARRAY, items: { type: Type.STRING } },
                  responseGood: { type: Type.ARRAY, items: { type: Type.STRING } },
                  responseBad: { type: Type.ARRAY, items: { type: Type.STRING } },
                },
              },
              part2: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  mainExpression: { type: Type.STRING },
                  explanation: { type: Type.STRING },
                  variations: { type: Type.ARRAY, items: { type: Type.STRING } },
                },
              },
              extra: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    expression: { type: Type.STRING },
                    meaning: { type: Type.STRING },
                    note: { type: Type.STRING },
                  },
                },
              },
            },
          },
          grammar: {
            type: Type.OBJECT,
            properties: {
              point1: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  construction: { type: Type.STRING },
                  examples: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        en: { type: Type.STRING },
                        ko: { type: Type.STRING },
                      },
                    },
                  },
                },
              },
              point2: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  construction: { type: Type.STRING },
                  examples: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        en: { type: Type.STRING },
                        ko: { type: Type.STRING },
                      },
                    },
                  },
                },
              },
            },
          },
          reading: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              subtitle: { type: Type.STRING },
              paragraphs: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    en: { type: Type.STRING },
                    ko: { type: Type.STRING },
                    grammarNote: { type: Type.STRING },
                  },
                },
              },
            },
          },
        },
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("No response from Gemini");

  try {
    return JSON.parse(text) as JikboData;
  } catch (e) {
    console.error("Failed to parse JSON", text);
    throw new Error("Invalid JSON format from Gemini");
  }
};

import React, { useState, useRef } from "react";
import { generateJikboData } from "./geminiService";
import { JikboData, AppStatus } from "./types";
import {
  ArrowUpTrayIcon,
  DocumentTextIcon,
  PrinterIcon,
} from "@heroicons/react/24/outline";

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [instruction, setInstruction] = useState<string>("동아(윤정미) 8과");
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [data, setData] = useState<JikboData | null>(null);
  const [error, setError] = useState<string>("");

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
    }
  };

  const handleGenerate = async () => {
    if (!file || !process.env.API_KEY) {
      setError("API Key or File missing.");
      return;
    }

    setStatus(AppStatus.PROCESSING);
    setError("");

    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64String = (reader.result as string).split(",")[1];
        try {
          const result = await generateJikboData(
            process.env.API_KEY!,
            base64String,
            file.type,
            instruction
          );
          setData(result);
          setStatus(AppStatus.SUCCESS);
        } catch (err: any) {
          setError(err.message || "Failed to generate content.");
          setStatus(AppStatus.ERROR);
        }
      };
      reader.readAsDataURL(file);
    } catch (e) {
      setError("Error reading file.");
      setStatus(AppStatus.ERROR);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  if (status === AppStatus.SUCCESS && data) {
    return (
      <div>
        {/* Toolbar - Hidden in Print */}
        <div className="fixed top-0 left-0 right-0 h-16 bg-white border-b shadow-sm flex items-center justify-between px-6 z-50 no-print">
          <div className="flex items-center gap-2">
            <h1 className="text-xl font-bold text-gray-800">
              Jikbo Generator
            </h1>
            <span className="text-sm px-2 py-1 bg-green-100 text-green-800 rounded-full">
              Ready
            </span>
          </div>
          <div className="flex gap-4">
             <button
              onClick={() => window.location.reload()}
              className="text-gray-600 hover:text-gray-900 font-medium"
            >
              New File
            </button>
            <button
              onClick={handlePrint}
              className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
            >
              <PrinterIcon className="w-5 h-5" />
              Print / Save PDF
            </button>
          </div>
        </div>

        {/* Print Content Container */}
        <div className="pt-20 pb-10 min-h-screen bg-gray-100 print:pt-0 print:pb-0 print:bg-white">
          <PageOne data={data} />
          <PageTwo data={data} />
          <PageThree data={data} />
          <PageFour data={data} />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
      <div className="bg-white max-w-lg w-full rounded-2xl shadow-xl p-8 border border-gray-100">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <DocumentTextIcon className="w-8 h-8 text-blue-600" />
          </div>
          <h1 className="text-2xl font-bold text-gray-900">
            기말고사 직전보강 Generator
          </h1>
          <p className="text-gray-500 mt-2">
            Upload your textbook PDF to generate a 4-page review sheet.
          </p>
        </div>

        <div className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              File Instruction (e.g., Textbook Name & Lesson)
            </label>
            <input
              type="text"
              value={instruction}
              onChange={(e) => setInstruction(e.target.value)}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
              placeholder="Ex: 중2 동아(윤) 8과"
            />
          </div>

          <div
            className={`border-2 border-dashed rounded-xl p-8 text-center transition-colors cursor-pointer ${
              file ? "border-blue-500 bg-blue-50" : "border-gray-300 hover:border-gray-400"
            }`}
            onClick={() => fileInputRef.current?.click()}
          >
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileChange}
              className="hidden"
              accept=".pdf,image/*"
            />
            {file ? (
              <div className="text-blue-600 font-medium flex flex-col items-center">
                <DocumentTextIcon className="w-8 h-8 mb-2" />
                {file.name}
              </div>
            ) : (
              <div className="text-gray-500 flex flex-col items-center">
                <ArrowUpTrayIcon className="w-8 h-8 mb-2" />
                <span>Click to upload PDF or Image</span>
              </div>
            )}
          </div>

          {error && (
            <div className="p-4 bg-red-50 text-red-600 rounded-lg text-sm">
              {error}
            </div>
          )}

          <button
            onClick={handleGenerate}
            disabled={status === AppStatus.PROCESSING || !file}
            className={`w-full py-4 rounded-xl text-white font-bold text-lg shadow-md transition-all ${
              status === AppStatus.PROCESSING || !file
                ? "bg-gray-400 cursor-not-allowed"
                : "bg-black hover:bg-gray-800"
            }`}
          >
            {status === AppStatus.PROCESSING ? (
              <span className="flex items-center justify-center gap-2">
                <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Processing with Gemini...
              </span>
            ) : (
              "Generate Jikbo"
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

// --- PDF Page Components ---

const PageHeader: React.FC<{ data: JikboData }> = ({ data }) => (
