                            <span className="text-[10px] bg-red-100 px-1 rounded">POINT</span> {p.grammarNote}
                         </p>
                      )}
                   </div>
                </div>
             </div>
          ))}
       </div>
       <div className="absolute bottom-2 right-4 text-[8pt] text-gray-300">p.4+</div>
    </div>
   );
}

