import React, { useState, useRef } from "react";
import { generateJikboData } from "./geminiService";
import { JikboData, AppStatus } from "./types";
import {
  ArrowUpTrayIcon,
  DocumentTextIcon,
  ArrowDownTrayIcon,
} from "@heroicons/react/24/outline";

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [instruction, setInstruction] = useState<string>("동아(윤정미) 8과");
  const [examType, setExamType] = useState<string>("기말고사"); // Default to Final
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [data, setData] = useState<JikboData | null>(null);
  const [error, setError] = useState<string>("");

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
    }
  };

  const handleGenerate = async () => {
    if (!file || !process.env.API_KEY) {
      setError("API 키 또는 파일이 누락되었습니다.");
      return;
    }

    setStatus(AppStatus.PROCESSING);
    setError("");

    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64String = (reader.result as string).split(",")[1];
        try {
          const result = await generateJikboData(
            process.env.API_KEY!,
            base64String,
            file.type,
            instruction
          );
          setData(result);
          setStatus(AppStatus.SUCCESS);
        } catch (err: any) {
          setError(err.message || "콘텐츠 생성에 실패했습니다.");
          setStatus(AppStatus.ERROR);
        }
      };
      reader.readAsDataURL(file);
    } catch (e) {
      setError("파일을 읽는 중 오류가 발생했습니다.");
      setStatus(AppStatus.ERROR);
    }
  };

  const handleExportHtml = () => {
    if (!data) return;

    // We construct the full HTML string here.
    // This duplicates the render logic but ensures a standalone HTML file.
    const htmlContent = `
<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${examType} 직전보강 - Zoops Jikbo Maker</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@300;400;500;700;900&display=swap');
      @import url('https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@400;700&display=swap');
      body { font-family: 'Noto Sans KR', sans-serif; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
      .serif { font-family: 'Noto Serif KR', serif; }
      .a4-page {
        width: 210mm; min-height: 297mm; background: white; margin: 0 auto; padding: 15mm;
        box-sizing: border-box; margin-bottom: 20px;
        box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
      }
      @media print {
        body { margin: 0; background: white; }
        .a4-page { width: 100%; margin: 0; padding: 0; box-shadow: none; min-height: auto; page-break-after: always; }
        .no-print { display: none !important; }
        .page-break { break-before: page; page-break-before: always; }
        .avoid-break { break-inside: avoid; page-break-inside: avoid; }
