                  </div>
                  <p class="mb-4 text-gray-700 leading-relaxed text-sm bg-gray-50 p-2 rounded">${data.grammar.point2.description || ''}</p>
                  <div class="space-y-2">
                     ${(data.grammar.point2.examples || []).map((ex, i) => `
                        <div class="flex gap-3 items-start p-2 hover:bg-gray-50 rounded">
