                           <div class="flex-1">
                              <p class="font-medium text-black">${ex.en}</p>
                              <p class="text-gray-500 text-[9pt]">${ex.ko}</p>
                           </div>
                        </div>`).join('')}
                  </div>
               </div>` : ''}
             </div>
             <div class="absolute bottom-2 right-4 text-[8pt] text-gray-300">p.3</div>
        </div>` : ''}

        <!-- Reading Section -->
        ${data.reading ? `
        <div class="a4-page relative page-break">
             <div class="flex justify-between items-end border-b-4 border-black pb-2 mb-6">
               <div>
                  <span class="text-xs text-gray-500 font-bold uppercase tracking-widest block mb-1">Reading Passage</span>
