             </div>

             <div class="flex flex-col gap-0 text-[10pt]">
                ${(data.reading.paragraphs || []).map((p, i) => `
                   <div class="flex gap-4 mb-4 avoid-break group">
                      <div class="flex-shrink-0 w-8 text-right">
