                            ${p.grammarNote ? `<p class="text-[8pt] text-red-600 font-bold flex items-center gap-1"><span class="text-[10px] bg-red-100 px-1 rounded">POINT</span> ${p.grammarNote}</p>` : ''}
                         </div>
                      </div>
                   </div>`).join('')}
             </div>
             <div class="absolute bottom-2 right-4 text-[8pt] text-gray-300">p.4+</div>
        </div>` : ''}
    </div>
</body>
</html>`;

    const blob = new Blob([htmlContent], { type: "text/html" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `Jikbo_${examType}_${data.meta.lesson}.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  if (status === AppStatus.SUCCESS && data) {
    return (
      <div className="bg-gray-200 min-h-screen pb-20">
