{
  "name": "Zoops Jikbo Maker",
  "description": "Generates a 4-page Exam Review (Jikbo) document from English textbook PDFs using Gemini.",
  "requestFramePermissions": []
}

import { GoogleGenAI, Type } from "@google/genai";
import { JikboData } from "./types";

export const generateJikboData = async (
  apiKey: string,
  base64File: string,
  mimeType: string,
  userInstruction: string
): Promise<JikboData> => {
  const ai = new GoogleGenAI({ apiKey });

  const systemInstruction = `You are an expert Korean middle school English teacher creating a "Jikbo" (Exam Last Minute Review) document.
  Analyze the provided textbook PDF/Image materials.
  Extract content to fill a strict JSON schema for a review sheet.

  Language: Korean (for explanations/definitions) and English (for content).

  Structure requirements:
  1. Vocabulary: 
     - Select the top 10 most important words for Synonyms.
     - Select the top 10 most important words for Antonyms.
     - Select the top 10 most important words for Definitions.
     - Focus on high-frequency exam words.
  2. Dialog: Identify 2 key communicative functions (Listen & Talk), their variations, and correct/incorrect responses.
  3. Grammar: Identify the 2 main grammar points of the lesson. Provide construction rules and examples.
  4. Reading: **Do NOT extract the full passage.** Instead, select 10 to 15 key sentences from the main text.
     - Prioritize sentences that contain the lesson's key grammar points.
     - Prioritize sentences that are crucial for understanding the story flow.
     - Provide the English sentence, a Korean translation, and a brief grammar point/note.

  If the file contains multiple lessons, focus on the lesson mentioned in the user instruction or the first full lesson found.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: mimeType,
            data: base64File,
          },
        },
        {
          text: `Generate Jikbo data. Context: ${userInstruction}. Return ONLY JSON.`,
        },
      ],
    },
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          meta: {
            type: Type.OBJECT,
            properties: {
              publisher: { type: Type.STRING, description: "e.g., 동아(윤)" },
              grade: { type: Type.STRING, description: "e.g., 2" },
              lesson: { type: Type.STRING, description: "e.g., Lesson 08" },
              schoolLevel: { type: Type.STRING, description: "e.g., MIDDLE SCHOOL" },
            },
          },
          vocab: {
            type: Type.OBJECT,
            properties: {
              synonyms: { type: Type.ARRAY, items: { type: Type.STRING }, description: "e.g., 'royal(왕의) = regal'" },
              antonyms: { type: Type.ARRAY, items: { type: Type.STRING }, description: "e.g., 'allow(허락하다) ↔ forbid(금지하다)'" },
              collocations: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Idioms or phrases" },
              definitions: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    word: { type: Type.STRING },
                    meaning: { type: Type.STRING },
                    enDefinition: { type: Type.STRING },
                  },
                },
              },
            },
          },
          dialog: {
            type: Type.OBJECT,
            properties: {
              part1: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  mainExpression: { type: Type.STRING },
                  explanation: { type: Type.STRING },
                  variations: { type: Type.ARRAY, items: { type: Type.STRING } },
                  responseGood: { type: Type.ARRAY, items: { type: Type.STRING } },
                  responseBad: { type: Type.ARRAY, items: { type: Type.STRING } },
                },
              },
              part2: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  mainExpression: { type: Type.STRING },
                  explanation: { type: Type.STRING },
                  variations: { type: Type.ARRAY, items: { type: Type.STRING } },
                },
              },
              extra: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    expression: { type: Type.STRING },
                    meaning: { type: Type.STRING },
                    note: { type: Type.STRING },
                  },
                },
              },
            },
          },
          grammar: {
            type: Type.OBJECT,
            properties: {
              point1: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  construction: { type: Type.STRING },
                  examples: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        en: { type: Type.STRING },
                        ko: { type: Type.STRING },
                      },
                    },
                  },
                },
              },
              point2: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  construction: { type: Type.STRING },
                  examples: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        en: { type: Type.STRING },
                        ko: { type: Type.STRING },
                      },
                    },
                  },
                },
              },
            },
          },
          reading: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              subtitle: { type: Type.STRING },
              paragraphs: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    en: { type: Type.STRING },
                    ko: { type: Type.STRING },
                    grammarNote: { type: Type.STRING },
                  },
                },
              },
            },
          },
        },
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("No response from Gemini");

  try {
    return JSON.parse(text) as JikboData;
  } catch (e) {
    console.error("Failed to parse JSON", text);
    throw new Error("Invalid JSON format from Gemini");
  }
};

import React, { useState, useRef } from "react";
import { generateJikboData } from "./geminiService";
import { JikboData, AppStatus } from "./types";
import {
  ArrowUpTrayIcon,
  DocumentTextIcon,
  PrinterIcon,
} from "@heroicons/react/24/outline";

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [instruction, setInstruction] = useState<string>("동아(윤정미) 8과");
  const [examType, setExamType] = useState<string>("기말고사");
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [data, setData] = useState<JikboData | null>(null);
  const [error, setError] = useState<string>("");

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
    }
  };

  const handleGenerate = async () => {
    if (!file || !process.env.API_KEY) {
      setError("API Key or File missing.");
      return;
    }

    setStatus(AppStatus.PROCESSING);
    setError("");

    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64String = (reader.result as string).split(",")[1];
        try {
          const result = await generateJikboData(
            process.env.API_KEY!,
            base64String,
            file.type,
            instruction
          );
          setData(result);
          setStatus(AppStatus.SUCCESS);
        } catch (err: any) {
          setError(err.message || "Failed to generate content.");
          setStatus(AppStatus.ERROR);
        }
      };
      reader.readAsDataURL(file);
    } catch (e) {
      setError("Error reading file.");
      setStatus(AppStatus.ERROR);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  if (status === AppStatus.SUCCESS && data) {
    return (
      <div className="bg-gray-200 min-h-screen pb-20">
        {/* Toolbar - Hidden in Print */}
        <div className="fixed top-0 left-0 right-0 h-16 bg-white border-b shadow-sm flex items-center justify-between px-6 z-50 no-print">
          <div className="flex items-center gap-2">
            <h1 className="text-xl font-bold text-gray-800">
              Zoops Jikbo Maker
            </h1>
            <span className="text-sm px-2 py-1 bg-green-100 text-green-800 rounded-full">
              Ready
            </span>
          </div>
          <div className="flex gap-4">
             <button
              onClick={() => window.location.reload()}
              className="text-gray-600 hover:text-gray-900 font-medium"
            >
              New File
            </button>
            <button
              onClick={handlePrint}
              className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
            >
              <PrinterIcon className="w-5 h-5" />
              Print / PDF
            </button>
          </div>
        </div>

        {/* Print Content Container */}
        <div className="pt-24 print:pt-0 flex flex-col items-center gap-8 print:block print:gap-0">
          <SectionVocab data={data} examTitle={examType} />
          <SectionDialog data={data} />
          <SectionGrammar data={data} />
          <SectionReading data={data} />
        </div>
      </div>
    );
  }

